<script setup lang="ts">import{ref,computed,onMounted,onBeforeUnmount,watch}from'vue';import{useGatewayStore}from'../stores/gateway';import{useConfigStore}from'../stores/config';import RetroClock from'./RetroClock.vue';import Tooltip from'./Tooltip.vue';import ConfirmDialog from'./ConfirmDialog.vue'
const g=useGatewayStore();const cfg=useConfigStore()
function ft(n:number):string{if(n>=1_000_000)return(n/1_000_000).toFixed(1)+'M';if(n>=1_000)return(n/1_000).toFixed(1)+'K';return String(n)}
const tc=ref(0);const skc=ref(0)
watch(()=>g.connected,v=>{if(v){g.request<{tool_count?:number;skill_count?:number}>('config.get',{key:'agent_stats'}).then(r=>{if(r){if(r.tool_count!==undefined)tc.value=r.tool_count;if(r.skill_count!==undefined)skc.value=r.skill_count}}).catch(()=>{})}},{immediate:true})
const sc=ref(false);let ct:ReturnType<typeof setTimeout>|null=null
function me(){if(ct)clearTimeout(ct);sc.value=true};function ml(){ct=setTimeout(()=>sc.value=false,250)}
const cl=computed(()=>g.usage.modelContextLimit||1_000_000);const tp=computed(()=>cl.value>0?Math.min(100,((g.usage.latestInputTokens+g.usage.latestOutputTokens)/cl.value)*100):0)
const crc=2*Math.PI*5.5;const of=computed(()=>crc-(tp.value/100)*crc);const dc=computed(()=>g.usage.sessionCostCny)
const cp=ref(false);const co=ref(false);const ao=ref(false);const am=ref('');const at=ref('')
async function hc(){if(cp.value||!g.sessionId)return;if(g.messages.length<2){at.value='Cannot compact';am.value=`Only ${g.messages.length} messages in this session; at least 2 are required to compact.`;ao.value=true;return};co.value=true}
async function cc(){co.value=false;if(!g.sessionId)return;cp.value=true;try{const r=await g.request<any>('session.compress',{session_id:g.sessionId});if(r.success){try{localStorage.removeItem(`pebble:messages:${g.sessionId}`)}catch{};await g.resumeSession(g.sessionId);at.value='Compaction complete';const bm=r.before?.messages||0;const amc=r.after?.messages||0;const kp=amc>2?amc-2:0;const ct=bm>kp?bm-kp:0;am.value=`Compacted: ${ct} messages\nKept: ${kp} messages\nSaved: ${r.saved_percent||0}%`;ao.value=true}else{at.value='Cannot compact';am.value=r.reason||'Compaction failed';ao.value=true}}catch{at.value='Compaction failed';am.value='Please try again later';ao.value=true}finally{cp.value=false}}
const ti=computed(()=>(g.usage.callHistory||[]).reduce((s,c)=>s+c.inputTokens,0))
const to=computed(()=>(g.usage.callHistory||[]).reduce((s,c)=>s+c.outputTokens,0))
const tch=computed(()=>(g.usage.callHistory||[]).reduce((s,c)=>s+(c.cacheHitTokens||0),0))
const mb=computed(()=>{const m:Record<string,{calls:number;cost:number;model:string}>= {};for(const c of (g.usage.callHistory||[])){const k=c.model||'unknown';if(!m[k])m[k]={calls:0,cost:0,model:k};m[k].calls++;m[k].cost+=c.costCny}return Object.values(m).sort((a,b)=>b.cost-a.cost)})
const chr=computed(()=>{const i=ti.value;const h=tch.value;if(i+h===0)return 0;return Math.round(h/(i+h)*100)})

// ===== 高峰/空闲时段监测（与后端 agent_chat_service_v2.is_peak_period 同一规则） =====
// 高峰 = 北京时间周一~周五 09:00-12:00、14:00-18:00（左闭右开）；其余（含周末、法定节假日全天）为空闲。
// 法定节假日列表由后端 config.get 'pricing' 的 cn_holidays 下发（与后端判定同源，本地预判同步排除）。
function isPeakLocal():boolean{const parts:Record<string,string>={};try{for(const p of new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()))parts[p.type]=p.value}catch{return false};const wd=parts.weekday||'';if(wd==='Sat'||wd==='Sun')return false;const ds=`${parts.year}-${(parts.month||'').padStart(2,'0')}-${(parts.day||'').padStart(2,'0')}`;if(peakInfo.value.holidays.includes(ds))return false;const h=parseInt(parts.hour||'0',10);return(h>=9&&h<12)||(h>=14&&h<18)}
const peakInfo=ref<{models:Record<string,{display_name?:string;pricing_peak?:Record<string,number>;pricing_offpeak?:Record<string,number>}>|null;backendPeriod:string|null;holidays:string[]}>({models:null,backendPeriod:null,holidays:[]})
const localPeriod=ref<'peak'|'offpeak'|null>(null);let _lastLocalPeriod:'peak'|'offpeak'|null=null;let _peakTimer:ReturnType<typeof setInterval>|null=null
async function refreshPeakInfo(force=false){const lp=isPeakLocal()?'peak':'offpeak';localPeriod.value=lp;if(force||lp!==_lastLocalPeriod){_lastLocalPeriod=lp;try{const r=await g.fetchPricing();if(r&&typeof r==='object'){const rd=r as {pricing?:{models?:Record<string,{display_name?:string;pricing_peak?:Record<string,number>;pricing_offpeak?:Record<string,number>}>};period?:string;cn_holidays?:{holidays?:string[]}};peakInfo.value={models:(rd.pricing&&rd.pricing.models)||null,backendPeriod:(rd.period as string)||lp,holidays:(rd.cn_holidays&&rd.cn_holidays.holidays)||peakInfo.value.holidays};const lp2=isPeakLocal()?'peak':'offpeak';if(lp2!==lp){localPeriod.value=lp2;_lastLocalPeriod=lp2}}else{peakInfo.value={...peakInfo.value,backendPeriod:lp}}}catch{peakInfo.value={...peakInfo.value,backendPeriod:lp}}}}
const activePeriod=computed<'peak'|'offpeak'|null>(()=>{const bp=peakInfo.value.backendPeriod;if(bp==='peak'||bp==='offpeak')return bp;const gp=g.usage.period;if(gp==='peak'||gp==='offpeak')return gp;return localPeriod.value})
const curModelName=computed<string|null>(()=>{const h=g.usage.callHistory||[];if(h.length>0){const lm=h[h.length-1].model;if(lm&&lm!=='unknown')return lm}try{const p=cfg.getActiveProvider();const pid=(p&&p.id)||cfg.activeProviderId;if(pid&&cfg.activeModel[pid])return cfg.activeModel[pid]}catch{}return null})
const curModelPricing=computed(()=>{const m=peakInfo.value.models;const n=curModelName.value;if(!m||!n)return null;return m[n]||null})
const isTimeBilling=computed(()=>{const p=curModelPricing.value;return!!(p&&p.pricing_peak&&p.pricing_offpeak)})
const peakPrice=computed(()=>curModelPricing.value?.pricing_peak||null);const offpeakPrice=computed(()=>curModelPricing.value?.pricing_offpeak||null)
const curModelDisplay=computed(()=>curModelPricing.value?.display_name||curModelName.value||'—')
const lastCallPeriod=computed<string|null>(()=>{const h=g.usage.callHistory||[];if(h.length===0)return null;const lp2=h[h.length-1].period;return(lp2==='peak'||lp2==='offpeak')?lp2:null})
function fmtPrice(n:number|undefined):string{if(typeof n!=='number')return'—';return n.toFixed(2)}
const _onPricingUpdated=()=>{refreshPeakInfo(true).catch(()=>{})}
onMounted(async()=>{await refreshPeakInfo(true).catch(()=>{});_peakTimer=setInterval(()=>{refreshPeakInfo().catch(()=>{})},60000);window.addEventListener('pricing-updated',_onPricingUpdated)})
onBeforeUnmount(()=>{if(_peakTimer){clearInterval(_peakTimer);_peakTimer=null};window.removeEventListener('pricing-updated',_onPricingUpdated)})
watch(()=>g.connected,v=>{if(v){refreshPeakInfo(true).catch(()=>{})}},{immediate:true})

</script>
<template><div class="sbar"><div class="sbar-l"><RetroClock/><span class="sbar-msgs"><svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/></svg>{{g.messages.length}}</span><span class="sbar-stat"><svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/></svg>{{tc}}</span><span class="sbar-stat"><svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>{{skc}}</span><span class="dot" :style="{background:g.connected?'var(--success)':'var(--error)'}"/><span>{{g.connected?'connected':'disconnected'}}</span><span v-if="g.sessionId" class="sbar-session">{{g.sessionId.slice(0,8)}}&hellip;</span></div><div class="sbar-r">
<span class="sbar-rate" :class="{idle:g.streamRate<=0}">{{Math.round(g.streamRate)}} tok/s</span>
<Tooltip :text="cp?'Compressing...':'Compress context'"><button class="sbar-compress" :class="{spinning:cp}" @click="hc" :disabled="cp"><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M21 16V8a2 2 0 00-1-1.73l-7-4a2 2 0 00-2 0l-7 4A2 2 0 003 8v8a2 2 0 001 1.73l7 4a2 2 0 002 0l7-4A2 2 0 0021 16z"/><polyline points="12 22 12 12"/><line x1="3.3" y1="7" x2="12" y2="12"/><line x1="20.7" y1="7" x2="12" y2="12"/></svg></button></Tooltip>
<div class="tr" @mouseenter="me" @mouseleave="ml"><svg viewBox="0 0 14 14"><circle cx="7" cy="7" r="5.5" fill="none" stroke="var(--border-subtle)" stroke-width="2"/><circle cx="7" cy="7" r="5.5" fill="none" :stroke="tp>80?'var(--error)':tp>50?'var(--warn)':'var(--accent)'" stroke-width="2" :stroke-dasharray="crc" :stroke-dashoffset="of" style="transition:stroke-dashoffset 0.5s ease"/></svg><span class="v">{{ft(g.usage.latestInputTokens+g.usage.latestOutputTokens)}}/{{ft(cl)}}</span></div>
<span class="cost" @mouseenter="me" @mouseleave="ml"><i v-if="isTimeBilling" class="cost-dot" :class="activePeriod==='peak'?'p':'o'"></i>{{dc.toFixed(3)}}CNY</span>
<div v-if="sc" class="cost-popup" @mouseenter="me" @mouseleave="sc=false"><div v-if="isTimeBilling" class="cp-period"><i class="cp-period-dot" :class="activePeriod==='peak'?'p':'o'"></i><span class="cp-period-txt">{{activePeriod==='peak'?'peak hours · higher rate':'off-peak hours · half price'}}</span></div>
<div v-if="isTimeBilling" class="cp-pt"><div class="cp-pt-head"><span>period</span><span>cache</span><span>input</span><span>output</span></div><div class="cp-pt-row" :class="{active:activePeriod==='peak'}"><span class="cp-pt-name">peak<em>09-12·14-18</em></span><span>{{fmtPrice(peakPrice?.cache_hit_per_million)}}</span><span>{{fmtPrice(peakPrice?.input_per_million)}}</span><span>{{fmtPrice(peakPrice?.output_per_million)}}</span></div><div class="cp-pt-row" :class="{active:activePeriod==='offpeak'}"><span class="cp-pt-name">off-peak<em>rest</em></span><span>{{fmtPrice(offpeakPrice?.cache_hit_per_million)}}</span><span>{{fmtPrice(offpeakPrice?.input_per_million)}}</span><span>{{fmtPrice(offpeakPrice?.output_per_million)}}</span></div><div class="cp-pt-sub">unit price CNY / 1M tokens</div></div>
<div v-if="isTimeBilling" class="cp-divider"/><div class="cp-model"><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/></svg><span class="cp-model-name">{{curModelDisplay}}</span></div><div class="cp-divider"/><div class="cp-grid"><div class="cp-cell"><span class="cp-cell-label">total cost</span><span class="cp-cell-value gold">{{g.usage.sessionCostCny.toFixed(4)}}<span class="cp-unit"> CNY</span></span></div><div class="cp-cell"><span class="cp-cell-label">api calls</span><span class="cp-cell-value">{{(g.usage.callHistory||[]).length}}</span></div><div class="cp-cell"><span class="cp-cell-label">input tokens</span><span class="cp-cell-value">{{ft(ti)}}</span></div><div class="cp-cell"><span class="cp-cell-label">output tokens</span><span class="cp-cell-value">{{ft(to)}}</span></div><div class="cp-cell"><span class="cp-cell-label">cache hit</span><span class="cp-cell-value dim">{{ft(tch)}}<span v-if="chr>0" class="cp-chip">{{chr}}%</span></span></div></div>
<div v-if="isTimeBilling&&lastCallPeriod" class="cp-last"><span class="cp-last-rate">last call @ <b>{{lastCallPeriod==='peak'?'peak':'off-peak'}}</b> rate</span><span v-if="activePeriod&&lastCallPeriod!==activePeriod" class="cp-last-warn">next call → {{activePeriod==='peak'?'peak':'off-peak'}}</span></div>
<div v-if="mb.length>1" class="cp-divider"/><div v-if="mb.length>1" class="cp-models"><div v-for="m in mb" :key="m.model" class="cp-model-row"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/></svg><span class="cp-model-name">{{m.model}}</span><span class="cp-model-calls">{{m.calls}} calls</span><span class="cp-model-cost">{{m.cost.toFixed(4)}} CNY</span></div></div><div v-if="(g.usage.callHistory||[]).length===0" class="cp-empty">no cost data yet</div></div>
<span>{{cfg.projectPath}}</span></div>
<ConfirmDialog :open="co" title="Compact Context" :message="`Current context is about ${g.usage.latestInputTokens.toLocaleString()} tokens.\n\nCompaction keeps recent messages and summarizes earlier ones.\n\nThis cannot be undone. Continue?`" confirm-label="Compact" cancel-label="Cancel" :danger="false" @confirm="cc" @cancel="co=false"/>
<ConfirmDialog :open="ao" :title="at" :message="am" confirm-label="OK" :danger="false" @confirm="ao=false" @cancel="ao=false"/></div></template>
